import pulp

# Problem data
# (job, operation) : (machine, processing_time)
jobs = {
    1: [(4, 9), (1, 8), (2, 6), (3, 8)],   # D1
    2: [(4, 1), (3, 6), (1, 6), (2, 6)],   # D2
    3: [(1,10), (3, 3), (4, 7), (2,10)],   # D3
    4: [(3, 2), (4, 9), (2, 1), (1, 2)]    # D4
}

# Create the model
model = pulp.LpProblem("plan", pulp.LpMinimize)

# Big M (sum of all processing times)
M = sum(p for ops in jobs.values() for (_, p) in ops) + 1  # 95

# Decision variables: start times
start = {}
for j, ops in jobs.items():
    for o, (m, p) in enumerate(ops, start=1):
        start[(j, o)] = pulp.LpVariable(f'start_{j}_{o}', lowBound=0, cat='Continuous')

# Binary variables for ordering on the same machine
y = {}
# Map each operation to a unique id for easier handling
op_id = {}
cnt = 0
for j, ops in jobs.items():
    for o, (m, p) in enumerate(ops, start=1):
        op_id[(j, o)] = cnt
        cnt += 1

# For each machine, collect operations that use it
machine_ops = {}
for j, ops in jobs.items():
    for o, (m, p) in enumerate(ops, start=1):
        machine_ops.setdefault(m, []).append((j, o))

# Create binary variables for each pair of operations on the same machine
for m, ops in machine_ops.items():
    for i in range(len(ops)):
        for k in range(i + 1, len(ops)):
            op_i = ops[i]
            op_k = ops[k]
            y[(op_i, op_k)] = pulp.LpVariable(f'y_{op_i[0]}_{op_i[1]}_{op_k[0]}_{op_k[1]}', cat='Binary')

# Makespan variable
Cmax = pulp.LpVariable('Cmax', lowBound=0, cat='Continuous')

# Objective: minimize makespan
model += Cmax

# Constraints

# 1. Precedence constraints within each job
for j, ops in jobs.items():
    for o in range(1, len(ops)):
        p_prev = ops[o-1][1]
        model += start[(j, o)] >= start[(j, o-1)] + p_prev

# 2. Machine constraints (no overlap)
for m, ops in machine_ops.items():
    for i in range(len(ops)):
        for k in range(i + 1, len(ops)):
            op_i = ops[i]
            op_k = ops[k]
            p_i = jobs[op_i[0]][op_i[1]-1][1]
            p_k = jobs[op_k[0]][op_k[1]-1][1]
            # op_i before op_k
            model += start[op_i] + p_i <= start[op_k] + M * (1 - y[(op_i, op_k)])
            # op_k before op_i
            model += start[op_k] + p_k <= start[op_i] + M * y[(op_i, op_k)]

# 3. Makespan constraints
for j, ops in jobs.items():
    for o, (m, p) in enumerate(ops, start=1):
        model += start[(j, o)] + p <= Cmax

# Solve the model
solver = pulp.HiGHS(msg=False, timeLimit=120)
model.solve(solver)

# Output results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Minimum makespan: {pulp.value(Cmax)}")
print("\nStart times:")
for j in sorted(jobs):
