import pulp

# Mapping of hub names to machine indices
hub_map = {'A': 0, 'B': 1, 'C': 2, 'D': 3}
rev_map = {v: k for k, v in hub_map.items()}

# Job data: list of (Hub, Duration) pairs for each route
jobs_data = {
    1: [('C', 5), ('B', 5), ('A', 7), ('D', 7)],
    2: [('D', 4), ('A', 5), ('C', 6), ('B', 1)],
    3: [('A', 8), ('B', 10), ('C', 2), ('D', 3)],
    4: [('C', 7), ('B', 8), ('A', 1), ('D', 2)]
}

# Convert to machine indices and durations
jobs = {}
for j, ops in jobs_data.items():
    jobs[j] = [(hub_map[hub], dur) for hub, dur in ops]

num_jobs = len(jobs)
num_ops = 4          # each route has 4 stages
M = 1000             # big‑M constant

# Create the optimization model
model = pulp.LpProblem("plan", pulp.LpMinimize)

# Start time variables for each operation
S = {}
for j in jobs:
    for k in range(num_ops):
        S[(j, k)] = pulp.LpVariable(f"S_{j}_{k}", lowBound=0, cat='Continuous')

# Makespan variable
Cmax = pulp.LpVariable("Cmax", lowBound=0, cat='Continuous')

# Objective: minimize makespan
model += Cmax

# Precedence constraints within each job
for j in jobs:
    for k in range(num_ops - 1):
        model += S[(j, k + 1)] >= S[(j, k)] + jobs[j][k][1]

# Collect operations per machine
ops_per_machine = {}
for j in jobs:
    for k in range(num_ops):
        m = jobs[j][k][0]
        ops_per_machine.setdefault(m, []).append((j, k))

# Binary ordering variables for operations on the same machine
y = {}
for m, ops in ops_per_machine.items():
    for i in range(len(ops)):
        for j in range(i + 1, len(ops)):
            op1 = ops[i]
            op2 = ops[j]
            y[(op1, op2)] = pulp.LpVariable(
                f"y_{op1[0]}_{op1[1]}_{op2[0]}_{op2[1]}", cat='Binary'
            )

# Disjunctive constraints for operations on the same machine
for m, ops in ops_per_machine.items():
    for i in range(len(ops)):
        for j in range(i + 1, len(ops)):
            op1 = ops[i]
            op2 = ops[j]
            j1, k1 = op1
            j2, k2 = op2
            p1 = jobs[j1][k1][1]
            p2 = jobs[j2][k2][1]
            # op1 before op2
            model += S[(j2, k2)] >= S[(j1, k1)] + p1 - M * (1 - y[(op1, op2)])
            # op2 before op1
            model += S[(j1, k1)] >= S[(j2, k2)] + p2 - M * y[(op1, op2)]

# Makespan constraints
for j in jobs:
    for k in range(num_ops):
        p = jobs[j][k][1]
        model += Cmax >= S[(j, k)] + p

# Solve the model with HiGHS
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Minimum makespan: {pulp.value(Cmax)}\n")

print("Schedule:")
for j in sorted(jobs):
    print(f"Route {j}:")
    for k in range(num_ops):
        op = jobs[j][k]
        start = pulp.value(S[(j, k)])
        hub_name = rev_map[op[0]]
        duration = op[1]
        print(f"  Stage {k+1} at Hub {hub_name}: start {start:.2f}, duration {duration}")
